sys_script.script:
(function executeRule(current, previous) {
    // Only enforce immutability when the record was already verified
    if (previous.getValue('otp_verified') != '1') {
        return;
    }

    // Fields that become immutable once verified
    var immutableFields = [
        'service_type',
        'technician_name',
        'cost',
        'service_date',
        'asset_passport',
        'otp_code',
        'otp_verified',
    ];

    for (var i = 0; i < immutableFields.length; i++) {
        var field = immutableFields[i];
        if (current.getValue(field) != previous.getValue(field)) {
            gs.addErrorMessage(
                'This service log has been verified and is now immutable. Only status and notes can be updated.'
            );
            current.setAbortAction(true);
            return;
        }
    }
})(current, previous);
